#define MAXN 100005

typedef struct Edge {
    int to;
    struct Edge *next;
} Edge;

Edge *adj[MAXN];
long long w[MAXN];
int visited[MAXN];
int N, M;

void add_edge(int u, int v) {
    Edge *e = malloc(sizeof(Edge));
    e->to = v;
    e->next = adj[u];
    adj[u] = e;
}

long long dfs(int u, int parent) {
    visited[u] = 1;
    long long best = 0;
    for (Edge *e = adj[u]; e; e = e->next) {
        int v = e->to;
        if (v == parent) continue;
        long long cand = dfs(v, u);
        if (cand > best) best = cand;
    }
    return w[u] + best;
}

