#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

typedef struct {
    int to, next;
} Edge;

typedef struct {
    int *v;
    int sz, cap;
} Vec;

static void vec_push(Vec *a, int x) {
    if (a->sz == a->cap) {
        a->cap = a->cap ? a->cap * 2 : 4;
        a->v = (int*)realloc(a->v, a->cap * sizeof(int));
    }
    a->v[a->sz++] = x;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    ll *w = (ll*)malloc((N + 1) * sizeof(ll));
    for (int i = 1; i <= N; i++) scanf("%lld", &w[i]);

    Edge *edges = (Edge*)malloc((2 * M + 5) * sizeof(Edge));
    int *head = (int*)malloc((N + 1) * sizeof(int));
    int *deg = (int*)calloc(N + 1, sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < M; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        edges[ecnt].to = v; edges[ecnt].next = head[u]; head[u] = ecnt++;
        edges[ecnt].to = u; edges[ecnt].next = head[v]; head[v] = ecnt++;
        deg[u]++; deg[v]++;
    }

    /* Iterative Tarjan for biconnected components (vertex-biconnected via edge stack) */
    int *dfn = (int*)calloc(N + 1, sizeof(int));
    int *low = (int*)calloc(N + 1, sizeof(int));
    int *parent = (int*)calloc(N + 1, sizeof(int));
    int *parentEdge = (int*)malloc((N + 1) * sizeof(int));
    int *iter = (int*)malloc((N + 1) * sizeof(int));
    int *stackV = (int*)malloc((N + 1) * sizeof(int));
    int topV = 0, timer = 0;

    int *estack = (int*)malloc((2 * M + 5) * sizeof(int));
    int topE = 0;

    Vec *bcc = NULL;
    int bccCnt = 0, bccCap = 0;

    for (int s = 1; s <= N; s++) {
        if (dfn[s]) continue;

        parent[s] = 0;
        parentEdge[s] = -1;
        dfn[s] = low[s] = ++timer;
        iter[s] = head[s];
        stackV[topV++] = s;

        while (topV) {
            int u = stackV[topV - 1];
            int *it = &iter[u];
            if (*it != -1) {
                int e = *it;
                *it = edges[e].next;
                int v = edges[e].to;

                if ((e ^ 1) == parentEdge[u]) continue;

                if (!dfn[v]) {
                    parent[v] = u;
                    parentEdge[v] = e;
                    estack[topE++] = e;
                    dfn[v] = low[v] = ++timer;
                    iter[v] = head[v];
                    stackV[topV++] = v;
                } else if (dfn[v] < dfn[u]) {
                    estack[topE++] = e;
                    if (dfn[v] < low[u]) low[u] = dfn[v];
                }
            } else {
                topV--;
                if (parent[u] != 0) {
                    int p = parent[u];
                    if (low[u] < low[p]) low[p] = low[u];

                    if (low[u] >= dfn[p]) {
                        if (bccCnt == bccCap) {
                            bccCap = bccCap ? bccCap * 2 : 4;
                            bcc = (Vec*)realloc(bcc, bccCap * sizeof(Vec));
                        }
                        bcc[bccCnt].v = NULL;
                        bcc[bccCnt].sz = bcc[bccCnt].cap = 0;

                        /* pop edges until parentEdge[u] */
                        while (1) {
                            int pe = estack[--topE];
                            int a = edges[pe ^ 1].to;
                            int b = edges[pe].to;
                            vec_push(&bcc[bccCnt], a);
                            vec_push(&bcc[bccCnt], b);
                            if (pe == parentEdge[u]) break;
                        }
                        bccCnt++;
                    }
                }
            }
        }
    }

    /* Build block-cut tree:
       original vertices: 1..N
       component nodes: N+1 .. N+bccCnt
    */
    int T = N + bccCnt;
    Vec *adj = (Vec*)calloc(T + 1, sizeof(Vec));

    char *mark = (char*)calloc(N + 1, sizeof(char));
    for (int i = 0; i < bccCnt; i++) {
        int cid = N + 1 + i;
        for (int j = 0; j < bcc[i].sz; j++) {
            int v = bcc[i].v[j];
            if (!mark[v]) {
                mark[v] = 1;
                vec_push(&adj[cid], v);
                vec_push(&adj[v], cid);
            }
        }
        for (int j = 0; j < bcc[i].sz; j++) mark[bcc[i].v[j]] = 0;
    }

    /* Weight of each node in block-cut tree:
       - articulation/original nodes keep their own weight
       - component node gets sum of weights of non-articulation vertices in it
         plus, if component contains vertex 1, include w[1] there and root answer from that component
       Then tree DP from the start side.
    */

    int *isArt = (int*)calloc(N + 1, sizeof(int));
    for (int v = 1; v <= N; v++) {
        if (adj[v].sz >= 2) isArt[v] = 1;
    }

    ll *val = (ll*)calloc(T + 1, sizeof(ll));
    for (int v = 1; v <= N; v++) {
        if (isArt[v]) val[v] = w[v];
    }

    int startNode = 1; /* in block-cut tree */
    if (!isArt[1]) {
        /* vertex 1 belongs to exactly one component if reachable at all */
        if (adj[1].sz > 0) startNode = adj[1].v[0];
        else {
            /* isolated single vertex */
            printf("%lld\n", w[1]);
            return 0;
        }
    }

    for (int cid = N + 1; cid <= T; cid++) {
        for (int i = 0; i < adj[cid].sz; i++) {
            int v = adj[cid].v[i];
            if (!isArt[v]) val[cid] += w[v];
        }
        if (!isArt[1]) {
            for (int i = 0; i < adj[cid].sz; i++) {
                if (adj[cid].v[i] == 1) {
                    val[cid] += w[1];
                    break;
                }
            }
        }
    }

    /* Tree DP for maximum connected subgraph containing startNode */
    int *par = (int*)calloc(T + 1, sizeof(int));
    int *order = (int*)malloc((T + 1) * sizeof(int));
    int qh = 0, qt = 0;
    order[qt++] = startNode;
    par[startNode] = -1;
    while (qh < qt) {
        int u = order[qh++];
        for (int i = 0; i < adj[u].sz; i++) {
            int v = adj[u].v[i];
            if (v == par[u]) continue;
            par[v] = u;
            order[qt++] = v;
        }
    }

    ll *dp = (ll*)calloc(T + 1, sizeof(ll));
    for (int i = qt - 1; i >= 0; i--) {
        int u = order[i];
        dp[u] = val[u];
        for (int j = 0; j < adj[u].sz; j++) {
            int v = adj[u].v[j];
            if (v == par[u]) continue;
            if (dp[v] > 0) dp[u] += dp[v];
        }
    }

    printf("%lld\n", dp[startNode]);
    return 0;
}

