#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<ll> w(N + 1);
    for (int i = 1; i <= N; ++i) cin >> w[i];

    vector<vector<int>> g(N + 1);
    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    // Find bridges with iterative DFS.
    vector<int> tin(N + 1, 0), low(N + 1, 0), parent(N + 1, -1), it(N + 1, 0);
    int timer = 0;
    set<pair<int,int>> bridges;

    for (int s = 1; s <= N; ++s) {
        if (tin[s]) continue;

        stack<int> st;
        st.push(s);
        parent[s] = 0;

        while (!st.empty()) {
            int v = st.top();

            if (!tin[v]) {
                tin[v] = low[v] = ++timer;
            }

            if (it[v] < (int)g[v].size()) {
                int to = g[v][it[v]++];
                if (to == parent[v]) continue;
                if (!tin[to]) {
                    parent[to] = v;
                    st.push(to);
                } else {
                    low[v] = min(low[v], tin[to]);
                }
            } else {
                st.pop();
                if (parent[v] != 0) {
                    int p = parent[v];
                    low[p] = min(low[p], low[v]);
                    if (low[v] > tin[p]) {
                        bridges.insert({min(p, v), max(p, v)});
                    }
                }
            }
        }
    }

    // Contract 2-edge-connected components (remove bridges).
    vector<int> comp(N + 1, -1);
    vector<ll> compSum;
    int comps = 0;

    for (int i = 1; i <= N; ++i) {
        if (comp[i] != -1) continue;
        queue<int> q;
        q.push(i);
        comp[i] = comps;
        ll sum = 0;

        while (!q.empty()) {
            int v = q.front();
            q.pop();
            sum += w[v];
            for (int to : g[v]) {
                if (bridges.count({min(v, to), max(v, to)})) continue;
                if (comp[to] == -1) {
                    comp[to] = comps;
                    q.push(to);
                }
            }
        }

        compSum.push_back(sum);
        ++comps;
    }

    // Build bridge tree.
    vector<vector<int>> tree(comps);
    for (auto [u, v] : bridges) {
        int cu = comp[u], cv = comp[v];
        tree[cu].push_back(cv);
        tree[cv].push_back(cu);
    }

    int root = comp[1];

    // Answer = maximum root-to-node path sum in the bridge tree.
    ll ans = 0;
    function<void(int,int,ll)> dfs = [&](int v, int p, ll cur) {
        cur += compSum[v];
        ans = max(ans, cur);
        for (int to : tree[v]) {
            if (to == p) continue;
            dfs(to, v, cur);
        }
    };

    dfs(root, -1, 0);

    cout << ans << '\n';
    return 0;
}

