        for (int i = 1; i <= N; i++) graph[i] = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            graph[u].add(v);
            graph[v].add(u);
        }

        boolean[] visited = new boolean[N + 1];
        dfs(1, -1, visited, values[1]);

        System.out.println(maxScore);
    }

    static void dfs(int u, int parent, boolean[] visited, long currentScore) {
        visited[u] = true;
        maxScore = Math.max(maxScore, currentScore);

        for (int v : graph[u]) {
            if (v == parent) continue; // cannot go back directly
            if (!visited[v]) {
                dfs(v, u, visited, currentScore + values[v]);
            } else {
                // already visited vertex, but can still go if not parent
                // no extra score, but we can still traverse
                dfs(v, u, visited, currentScore);
            }
        }

        visited[u] = false; // backtrack for other paths
    }
}

