public class Main {
    static int N, M;
    static int[] w;
    static List<int[]>[] adj; // [neighbor, edge_index]
    static Map<Long, Integer> memo = new HashMap<>();

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt(); M = sc.nextInt();
        w = new int[N+1];
        for(int i=1;i<=N;i++) w[i]=sc.nextInt();
        adj = new List[N+1];
        for(int i=1;i<=N;i++) adj[i]=new ArrayList<>();
        for(int i=0;i<M;i++){
            int u=sc.nextInt(),v=sc.nextInt();
            adj[u].add(new int[]{v,i});
            adj[v].add(new int[]{u,i});
        }
        int visited = 1; // vertex 1 visited
        System.out.println(w[1] + dfs(1, -1, visited));
    }

    static int dfs(int u, int lastEdge, int visited){
        long key = ((long)u)*100000L*((long)(1<<N)) + (long)(lastEdge+1)*(1<<N) + visited;
        if(memo.containsKey(key)) return memo.get(key);
        int best=0;
        for(int[] e: adj[u]){
            int v=e[0], ei=e[1];
            if(ei==lastEdge) continue;
            int gain=(visited&(1<<(v-1)))==0?w[v]:0;
            int res=gain+dfs(v,ei,visited|(1<<(v-1)));
            best=Math.max(best,res);
        }
        memo.put(key,best);
        return best;
    }
}

