import java.util.*;

/*
We need the maximum total value collectable in an undirected graph.
Start at vertex 1.
Move along edges, with the only restriction: you cannot traverse the same edge immediately back
(i.e. if you came to v from u, your next move cannot be v -> u).

A vertex value is counted only the first time it is visited.

Key observation:
- Inside any biconnected component (in the bridge-tree sense), once you enter it, you can collect
  all vertex values in that component before leaving, because there is always a walk avoiding
  immediate backtracking that can traverse the component and eventually exit through any needed cut vertex.
- Bridges are the only places where movement direction matters globally.
- After compressing each 2-edge-connected component (bridge-connected component), the graph becomes a tree.
- Starting from the component containing vertex 1, because immediate reversal on a bridge is forbidden,
  once you cross a bridge from parent component to child component, you can never return to the parent
  through that same bridge immediately; on a tree there is no alternative route, so effectively you choose
  one downward path in the bridge-tree.
Thus the answer is:
sum of values in start component + maximum path sum from that component in the bridge-tree.

So:
1) Find all bridges with Tarjan.
2) Build components ignoring bridges.
3) Sum weights per component.
4) Build bridge-tree.
5) DFS from start component to find maximum root-to-node path sum.

Complexities: O(N + M)
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int to, id;
        Edge(int to, int id) {
            this.to = to;
            this.id = id;
        }
    }

    static int N, M;
    static long[] w;
    static int[] U, V;

    static ArrayList<Edge>[] g;

    static int timer = 0;
    static int[] tin, low;
    static boolean[] isBridge;

    static void dfsBridge(int v, int pe) {
        tin[v] = low[v] = ++timer;
        for (Edge e : g[v]) {
            if (e.id == pe) continue;
            int to = e.to;
            if (tin[to] == 0) {
                dfsBridge(to, e.id);
                low[v] = Math.min(low[v], low[to]);
                if (low[to] > tin[v]) isBridge[e.id] = true;
            } else {
                low[v] = Math.min(low[v], tin[to]);
            }
        }
    }

    static int[] comp;
    static long[] compSum;
    static int compCnt = 0;

    static void dfsComp(int start) {
        ArrayDeque<Integer> st = new ArrayDeque<>();
        st.push(start);
        comp[start] = compCnt;
        long sum = 0;

        while (!st.isEmpty()) {
            int v = st.pop();
            sum += w[v];
            for (Edge e : g[v]) {
                if (isBridge[e.id]) continue;
                int to = e.to;
                if (comp[to] == -1) {
                    comp[to] = compCnt;
                    st.push(to);
                }
            }
        }
        compSum[compCnt] = sum;
    }

    static ArrayList<Integer>[] tree;
    static long ans = 0;

    static void dfsTree(int v, int p, long cur) {
        ans = Math.max(ans, cur);
        for (int to : tree[v]) {
            if (to == p) continue;
            dfsTree(to, v, cur + compSum[to]);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        N = fs.nextInt();
        M = fs.nextInt();

        w = new long[N + 1];
        for (int i = 1; i <= N; i++) w[i] = fs.nextLong();

        U = new int[M];
        V = new int[M];
        g = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            U[i] = u;
            V[i] = v;
            g[u].add(new Edge(v, i));
            g[v].add(new Edge(u, i));
        }

        tin = new int[N + 1];
        low = new int[N + 1];
        isBridge = new boolean[M];

        dfsBridge(1, -1);

        comp = new int[N + 1];
        Arrays.fill(comp, -1);
        compSum = new long[N + 1];

        for (int i = 1; i <= N; i++) {
            if (tin[i] != 0 && comp[i] == -1) {
                dfsComp(i);
                compCnt++;
            }
        }

        tree = new ArrayList[compCnt];
        for (int i = 0; i < compCnt; i++) tree[i] = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            if (isBridge[i]) {
                int a = comp[U[i]];
                int b = comp[V[i]];
                if (a != b) {
                    tree[a].add(b);
                    tree[b].add(a);
                }
            }
        }

        int startComp = comp[1];
        ans = compSum[startComp];
        dfsTree(startComp, -1, compSum[startComp]);

